---@class OverseaManageCafeCattyStarNodeCell
local OverseaManageCafeCattyStarNodeCell = Class('OverseaManageCafeCattyStarNodeCell')
local KTool = CS.Engine.Lib.KTool
local UIModule          = CS.Engine.UI.UIModule
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")

function OverseaManageCafeCattyStarNodeCell:__init()
    
end

function OverseaManageCafeCattyStarNodeCell:__delete()
    
end

function OverseaManageCafeCattyStarNodeCell:Awake()
    self:AddUIClick()
    self:InitNode()
end

function OverseaManageCafeCattyStarNodeCell:AddUIClick()
    SetButtonAction(self.controller,Bind(self,self.OnStarCellClick))
end

function OverseaManageCafeCattyStarNodeCell:SetStarIndex(index)
    self.starIndex = index
end

function OverseaManageCafeCattyStarNodeCell:SetStarCellCallBack(callBack)
    self.callBack = callBack
end

function OverseaManageCafeCattyStarNodeCell:InitNode()
    KTool.SetActive(self.ImgStarGrey.gameObject,false)
    KTool.SetActive(self.CanLight.gameObject,false)
    KTool.SetActive(self.StarGet.gameObject,false)
    KTool.SetActive(self.ImgStarSelect.gameObject,false)
    KTool.SetActive(self.LvCircleGroup.gameObject,false)
    self:SetCircleStatus(1)
end
---lightCircle  表示要亮起多少个点
function OverseaManageCafeCattyStarNodeCell:SetCircleStatus(status,lightCircle)
    for i = 1, 5 do
        local circle = self["ImgCircle"..i]
        if circle then
            if lightCircle then
                circle.Status = i > lightCircle and 1 or 2
            else
                circle.Status = status
            end
        end
    end
end

function OverseaManageCafeCattyStarNodeCell:OnStarCellClick()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isLevelUp = component:GetCurIsLevelUp()
    if isLevelUp then
        KTool.SetActive(self.ImgStarSelect.gameObject,true)
        local parameters = {
            callBack = function() KTool.SetActive(self.ImgStarSelect.gameObject,false)  end,
            pos = {-511,138},
            starIndex = self.starIndex
        }
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCattyStarTip,parameters = parameters })
    end
end

function OverseaManageCafeCattyStarNodeCell:SetFullStarShow()
    KTool.SetActive(self.StarGet.gameObject,true)
    KTool.SetActive(self.LvCircleGroup.gameObject,false)
    KTool.SetActive(self.CanLight.gameObject,false)
    --self:SetCircleStatus(2)
end

function OverseaManageCafeCattyStarNodeCell:SetCurStarShow(level)
    if not isNull(level) and level == MaidCoffeeConstants.StarUpNeedLevel then
        KTool.SetActive(self.CanLight.gameObject,true)
    else
        KTool.SetActive(self.CanLight.gameObject,false)
    end
    KTool.SetActive(self.LvCircleGroup.gameObject,true)
    KTool.SetActive(self.ImgStarGrey.gameObject,false)
    self:SetCircleStatus(1,level)
end

function OverseaManageCafeCattyStarNodeCell:SetNextStarShow()
    KTool.SetActive(self.ImgStarGrey.gameObject,true)
    KTool.SetActive(self.LvCircleGroup.gameObject,false)
    --self:SetCircleStatus(1)
end

function OverseaManageCafeCattyStarNodeCell:SetStarGetStatus(status)
    KTool.SetActive(self.StarGet.gameObject,status)
end

function OverseaManageCafeCattyStarNodeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageCafeCattyStarNodeCell